// Weekly numbers from the leads table. Counts only; no estimates.
const since = Date.now() - 7 * 86400e3;
const rows = $input.all().map(i => i.json).filter(r => r.lead_id && new Date(r.received_at).getTime() >= since);
const n = rows.length;
const count = (f) => rows.filter(f).length;
const pct = (x) => n ? Math.round((x / n) * 100) + '%' : '-';
const mins = rows.filter(r => r.response_minutes !== null && r.response_minutes !== undefined && r.response_minutes !== '').map(r => Number(r.response_minutes)).filter(x => !isNaN(x)).sort((a, b) => a - b);
const median = mins.length ? mins[Math.floor((mins.length - 1) / 2)] : null;
const byStatus = {};
for (const r of rows) byStatus[r.status] = (byStatus[r.status] || 0) + 1;
const gaps = {};
for (const r of rows) for (const g of String(r.jobs_unmatched || '').split(';').map(x => x.trim()).filter(Boolean)) gaps[g] = (gaps[g] || 0) + 1;
const topGaps = Object.entries(gaps).sort((a, b) => b[1] - a[1]).slice(0, 5);
const channels = {};
for (const r of rows) channels[r.channel] = (channels[r.channel] || 0) + 1;

const s = $('Load settings').first().json;
const text = [
  'Weekly lead report – ' + s.garage_name,
  '',
  'Leads in the last 7 days: ' + n + (n ? ' (' + Object.entries(channels).map(([k, v]) => k + ' ' + v).join(', ') + ')' : ''),
  'Answered automatically: ' + count(r => r.route === 'auto') + ' (' + pct(count(r => r.route === 'auto')) + ')',
  'Median time to first reply: ' + (median === null ? '-' : median + ' min'),
  'Booking requests: ' + count(r => r.status === 'booking_requested') + ' (' + pct(count(r => r.status === 'booking_requested')) + ')',
  'Waiting for your call: ' + count(r => r.status === 'needs_call'),
  'No reply after follow-ups: ' + count(r => r.status === 'lost_no_reply'),
  '',
  'By status: ' + (Object.entries(byStatus).map(([k, v]) => k + ' ' + v).join(', ') || '-'),
  '',
  'Requests not in your price book (consider adding):',
  ...(topGaps.length ? topGaps.map(([g, c]) => '• ' + g + ' (' + c + ')') : ['• none']),
].join('\n');
return [{ json: { text, leads: n } }];
